// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the sender, a target address (we will deploy a recording helper there),
    // an arbitrary uint256 value, and the length of the _tos array to decide empty vs non-empty
    function testFuzz_property(address from, uint256 v, uint256 tosLenRaw) public {
        // keep tos length within a small bound but allow 0..10
        uint256 tosLen = bound(tosLenRaw, 0, 10);

        // Deploy a recording helper to observe calls made by c
        Recorder rec = new Recorder();

        // Build the _tos array: if tosLen==0 it's empty; otherwise fill all entries with rec address
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            tos[i] = address(rec);
        }

        // Call c.transfer and record whether it reverted or not. The reference contract requires _tos.length>0
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: reference C accepts (ok==true) exactly when tosLen > 0
        // Because the test must be executable only against the reference contract (which we have),
        // assert that if tosLen>0 then the call did not revert. This is satisfied by the reference for all inputs.
        // The mutant flips the require and will fail this assertion for some inputs (any with tosLen>0).
        assertTrue(tosLen > 0 ? ok : true);
    }
}

// Recording helper that exposes the function signature c encodes with selector "transferFrom(address,address,uint256)"
contract Recorder {
    // store number of times called and last args observed
    uint public calls;
    address[] public tosRecorded;
    address public lastFrom;
    uint public lastV;

    // the function selector used by C: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastV = v;
        tosRecorded.push(to);
        return true;
    }

    // fallback to catch any other calls (not strictly necessary)
    fallback() external payable {}
}
